morse.watch("#__next > div:nth-of-type(2) > main > div:nth-of-type(1)", bar => {
  if (bar.querySelector("[data-sort-price]")) return;
  let original = null;
  let sorted = false;
  const price = c => {
    const m = c.textContent.match(/\$\s*([\d,]+(?:\.\d+)?)/);
    return m ? parseFloat(m[1].replace(/,/g, "")) : 1e9;
  };
  const btn = morse.el("button", {
    "data-sort-price": "",
    type: "button",
    text: "Sort: price ↑",
    style: "margin-left:auto;font:inherit;font-size:13px;color:inherit;background:transparent;border:1px solid currentColor;border-radius:6px;padding:4px 10px;cursor:pointer;opacity:.8",
    on: {
      click: () => {
        const grid = morse.$$("#__next > div:nth-of-type(2) > main > div:nth-of-type(2)")[0];
        if (!grid) return;
        const cards = [...grid.children];
        if (!original) original = cards.slice();
        if (!sorted) {
          cards.slice().sort((a, b) => price(a) - price(b)).forEach(c => grid.appendChild(c));
          btn.textContent = "Sort: default";
        } else {
          original.forEach(c => grid.appendChild(c));
          btn.textContent = "Sort: price ↑";
        }
        sorted = !sorted;
      }
    }
  });
  bar.appendChild(btn);
});
